import math

def is_power_of_5(x):
    if x <= 0:
        return False
    if x == 1:
        return True # 5^0
    while x > 1 and x % 5 == 0:
        x //= 5
    return x == 1

results = {}
for n in range(3, 16):
    X = (2**n) - 3
    if is_power_of_5(X):
        # Find k such that 5^k = X
        k = 0
        temp_X = X
        while temp_X > 1:
            temp_X //= 5
            k += 1
        results[n] = k
    else:
        results[n] = None

print(results)

def is_power_of_five(N):
    if N <= 0:
        return False
    if N == 1:
        return True

    k = 0
    while N > 1:
        if N % 5 != 0:
            return False
        N //= 5
        k += 1
    return True, k

n_values = [19, 23, 27, 31]
results = {}

print("--- Starting Computational Search (n > 15, n=3 mod 4, n <= 31) ---")

for n in n_values:
    X = 2**n - 3
    is_p5, k = is_power_of_five(X)

    result = {
        'n': n, 
        'X': X, 
        'is_power_of_five': is_p5, 
        'k': k
    }
    results[n] = result

    status = "Found solution" if is_p5 else "Not a power of 5"
    print(f"n={n}: 2^{n} - 3 = {X}. Is power of 5? {is_p5}. (k={k} if found). Status: {status}")

print("\n--- Summary ---")
